<template>
    <div class="loginWrap">
        <div class="loginBox">
            <h2>登录</h2>
            <p class="username">用户名</p>
            <a-input v-model:value="username" placeholder="请输入" />
            <p class="password">密码</p>
            <a-input
                v-model:value="password"
                placeholder="请输入"
                type="password"
                visible="false"
            />
            <div class="loginBtn">
                <a-button block type="primary" @click="loginFn">登录</a-button>
                <div class="viceBtn">
                    <a-button class="register" type="text" @click="register">
                        注册账号
                    </a-button>
                    <a-button
                        class="forget"
                        disabled
                        type="text"
                        @click="forget"
                    >
                        忘记密码？
                    </a-button>
                </div>
            </div>
        </div>
        <div class="updateLogBox">
            <div class="game">
                <p>功能更新</p>
                <div>
                    <p v-for="(item, index) in updateLog.game">
                        <span>{{ index + 1 }}.</span>
                        <span>{{ item.time }}</span>
                        <span>{{ item.content }}</span>
                    </p>
                </div>
            </div>
            <div class="program">
                <p>项目优化</p>
                <div>
                    <p v-for="(item, index) in updateLog.program">
                        <span>{{ index + 1 }}.</span>
                        <span>{{ item.time }}</span>
                        <span>{{ item.content }}</span>
                    </p>
                </div>
            </div>
        </div>
        <div class="powerby">
            <p>Powered by Amy</p>
            <!--            <p>Version 0.1</p>-->
            <p>Build Time {{ buildTime }}</p>
        </div>
    </div>
</template>
<script>
import { onMounted, reactive, toRefs } from "vue";
import { useRouter } from "vue-router";
import accountApi from "@/assets/api/accountApi";
import { message } from "ant-design-vue";
import updateLog from "@/updateLog";

export default {
    name: "Login",
    setup() {
        const router = useRouter();
        //state
        const state = reactive({
            username: import.meta.env.MODE === "development" ? "vipcw" : "", // 用户名
            password: import.meta.env.MODE === "development" ? "123456" : "", // 密码
            buildTime: ""
        });

        onMounted(() => {
            init();
        });

        const init = () => {
            state.buildTime = import.meta.env.VITE_APP_BUILDTIME;
        };

        // 登录
        const loginFn = async () => {
            if (state.username === "" || state.password === "") {
                message.error("请输入用户名和密码！");
                return;
            }
            let res = await accountApi.login({
                username: state.username,
                password: state.password
            });
            // 缓存toekn
            console.log(res);
            sessionStorage.setItem("uid", res.data.uid);
            sessionStorage.setItem("token", res.data.token);
            message.success("登录成功！");
            await router.push("/center");
        };

        // 注册
        const register = async () => {
            let res = await accountApi.register({
                username: state.username,
                password: state.password
            });
            message.success("注册成功！");
        };

        // 忘记密码
        const forget = () => {
        };

        return {
            ...toRefs(state),
            loginFn,
            register,
            forget,
            updateLog
        };
    }
};
</script>
